import Foundation

/// A non-SPM open source component bundled in the app (e.g. the vendored
/// llama.cpp sources compiled into the app), loaded from
/// ThirdPartyLicenses.json. Swift package licenses are handled separately by
/// the LicenseList package.
///
/// ThirdPartyLicenses.json is generated by ios/generate-third-party-licenses.py.
/// Regenerate when the vendored llama.cpp submodule is bumped.
struct Acknowledgement: Identifiable, Decodable {
    let name: String
    let license: String
    let text: String
    var id: String { name }
}

enum Acknowledgements {
    static let all: [Acknowledgement] = {
        guard let url = Bundle.main.url(forResource: "ThirdPartyLicenses", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let entries = try? JSONDecoder().decode([Acknowledgement].self, from: data)
        else {
            assertionFailure("ThirdPartyLicenses.json missing or malformed")
            return []
        }
        return entries
    }()
}
